WITH totals AS (
  SELECT shop, SUM(amount) AS total
  FROM snacks
  GROUP BY shop
)
SELECT shop, total FROM totals WHERE total >= 40;

SELECT day, amount,
  SUM(amount) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
FROM daily;

WITH ranked AS (
  SELECT name, amount, DENSE_RANK() OVER (ORDER BY amount DESC) AS place
  FROM snacks
)
SELECT name, amount, place FROM ranked WHERE place <= 2;

SELECT f.name, m.name AS mentor
FROM friends AS f
LEFT JOIN friends AS m ON f.mentor_id = m.id;

WITH visits_all AS (
  SELECT name FROM morning
  UNION ALL
  SELECT name FROM evening
)
SELECT name, COUNT(*) AS visits FROM visits_all GROUP BY name;

SELECT product, 1.0 * SUM(reordered) / COUNT(*) AS reorder_rate
FROM orders
GROUP BY product;

